.eon8-live-page .services-section {
    background: #ffffff;
    padding: 35px 20px;
    text-align: center;
    color: #111827;
}
.eon8-live-page .services-section h2 {
    font-size: 34px;
    margin-bottom: 10px;
    font-weight: 600;
    color: #111827;

    opacity: 0;
    transform: translateY(30px);
    transition: 0.6s ease;
}
.eon8-live-page .services-section .subtitle {
    max-width: 800px;
    margin: 0 auto 50px;
    color: #6b7280;
    font-size: 16px;

    opacity: 0;
    transform: translateY(30px);
    transition: 0.6s ease;
}
.eon8-live-page .services-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 25px;
}
.eon8-live-page .service-card {
    background: #ffffff;
    color: #1e293b;
    padding: 25px;
    border-radius: 16px;
    text-align: center;
    transition: 0.35s ease;

    border: 1px solid #e5e7eb;
    box-shadow: 0 5px 20px rgba(0,0,0,0.04);

    opacity: 0;
    transform: translateY(50px) scale(0.95);
}
.eon8-live-page .service-card .icon {
    width: 65px;
    height: 65px;
    margin: 0 auto 18px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: linear-gradient(135deg, #2563eb, #3b82f6);
    border-radius: 50%;

    font-size: 28px;

    transform: scale(0.8);
    transition: 0.3s ease;
}
.eon8-live-page .service-card h3 {
    font-size: 18px;
    margin-bottom: 12px;
    font-weight: 600;
    color: #111827;
}
.eon8-live-page .service-card p {
    font-size: 14px;
    color: #6b7280;
    line-height: 1.7;
}
.eon8-live-page .service-card:hover {
    transform: translateY(-10px) scale(1.03);
    box-shadow: 0 15px 35px rgba(0,0,0,0.08);
}
.eon8-live-page .service-card:hover .icon {
    transform: scale(1.15);
}
.eon8-live-page .services-section.show h2 {
    opacity: 1;
    transform: translateY(0);
}
.eon8-live-page .services-section.show .subtitle {
    opacity: 1;
    transform: translateY(0);
    transition-delay: 0.1s;
}
.eon8-live-page .services-section.show .service-card:nth-child(1) {
    opacity: 1; 
    transform: translateY(0) scale(1); 
    transition-delay: 0.2s;
}
.eon8-live-page .services-section.show .service-card:nth-child(2) {
    opacity: 1; 
    transform: translateY(0) scale(1); 
    transition-delay: 0.3s;
}
.eon8-live-page .services-section.show .service-card:nth-child(3) {
    opacity: 1; 
    transform: translateY(0) scale(1); 
    transition-delay: 0.4s;
}
.eon8-live-page .services-section.show .service-card:nth-child(4) {
    opacity: 1; 
    transform: translateY(0) scale(1); 
    transition-delay: 0.5s;
}
.eon8-live-page .services-section.show .service-card:nth-child(5) {
    opacity: 1; 
    transform: translateY(0) scale(1); 
    transition-delay: 0.6s;
}
.eon8-live-page .services-section.show .icon {
    transform: scale(1);
}
@media (max-width: 992px) {.eon8-live-page .services-grid {
        grid-template-columns: repeat(2, 1fr);
    }}
@media (max-width: 600px) {.eon8-live-page .services-grid {
        grid-template-columns: 1fr;
    }
