.eon8-live-page .cta-section {
    background: linear-gradient(135deg, #1f1f1f, #2a2a2a, #3a3a3a);
    padding: 15px 20px;
    text-align: center;
    position: relative;
    overflow: hidden;
}
.eon8-live-page .cta-section::after {
    content: "";
    position: absolute;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(255,255,255,0.08), transparent 70%);
    top: -100px;
    right: -100px;
}
.eon8-live-page .cta-container {
    max-width: 820px;
    margin: auto;
    position: relative;
    z-index: 2;
}
.eon8-live-page .cta-section h2 {
    color: #ffffff;
    font-size: 36px;
    margin-bottom: 20px;
    font-weight: 600;
    letter-spacing: 0.3px;
}
.eon8-live-page .cta-section p {
    color: #d4d4d8;
    font-size: 16px;
    line-height: 1.7;
    margin-bottom: 18px;
}
.eon8-live-page .cta-sub {
    color: #a1a1aa;
}
.eon8-live-page .cta-btn {
    display: inline-block;
    margin-top: 25px;
    padding: 14px 32px;
    background: linear-gradient(135deg, #ffffff, #e5e5e5);
    color: #111;
    border-radius: 10px;
    font-size: 16px;
    font-weight: 600;
    text-decoration: none;
    transition: all 0.3s ease;
    box-shadow: 0 8px 25px rgba(0,0,0,0.2);
}
.eon8-live-page .cta-btn:hover {
    transform: translateY(-3px);
    box-shadow: 0 12px 35px rgba(0,0,0,0.3);
}
.eon8-live-page .cta-section::before {
    content: "";
    display: block;
    width: 70px;
    height: 3px;
    background: linear-gradient(to right, transparent, #fff, transparent);
    margin: 0 auto 30px;
    opacity: 0.4;
}
@media (max-width: 768px) {.eon8-live-page .cta-section h2 {
        font-size: 28px;
    }}
.eon8-live-page .faq-section {
  padding: 0px 20px;

}
.eon8-live-page .faq-container {
  max-width: 800px;
  margin: 40px auto 0;
}
.eon8-live-page .faq-item {
  background: #ffffff;
  border-radius: 10px;
  margin-bottom: 15px;
  padding: 0 20px;
  box-shadow: 0 5px 20px rgba(0,0,0,0.05);
  border: 1px solid #eef1f5;
  transition: 0.3s ease;
}
.eon8-live-page .faq-item:hover {
  box-shadow: 0 8px 25px rgba(0,0,0,0.08);
}
.eon8-live-page .faq-question {
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: 18px 0;
  font-size: 16px;
  font-weight: 600;
  color: #0a2a5e;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
}
.eon8-live-page .faq-question span {
  font-size: 20px;
  color: #ff6a00;
  transition: 0.3s;
}
.eon8-live-page .faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: all 0.35s ease;
}
.eon8-live-page .faq-answer p {
  padding-bottom: 15px;
  color: #555;
  font-size: 14px;
  line-height: 1.6;
}
.eon8-live-page .faq-item.active {
  border-color: #ff6a00;
}
.eon8-live-page .faq-item.active .faq-answer {
  max-height: 300px;
}
.eon8-live-page .faq-item.active .faq-question span {
  transform: rotate(45deg);
}
